insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Bluegrass Distillers Mash Bill #1 Small Batch","rar":"shelf","f":"Bluegrass Distillers","x":"Mash Bill #1 Small Batch","p":100.0,"ay":null,"al":null,"nas":false,"et":"small_batch","ms":"high_rye","mb":"75% Yellow Corn, 21% Rye, 4% Malted Barley","st":"bourbon","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":["Bluegrass Distillers Mash Bill #1 Small Batch Bourbon"],"img":"https://bluegrassdistillers.com/wp-content/uploads/2025/11/100-proof-mash-bill-1-bourbon.webp","u":"https://bluegrassdistillers.com/products/100-proof-mash-bill-1-bourbon/","pr":"Bluegrass","mk":"b777795d-6400-4663-baf6-1b19a8518b04"},{"n":"Bluegrass Distillers Mash Bill #1 Bottled-in-Bond","rar":"limited","f":"Bluegrass Distillers","x":"Mash Bill #1 Bottled-in-Bond","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"high_rye","mb":"75% Yellow Corn, 21% Rye, 4% Malted Barley","st":"bourbon","bib":true,"bp":false,"fin":null,"msrp":null,"core":false,"al2":["Bluegrass Distillers Mash Bill #1 Bottled-in-Bond Bourbon"],"img":"https://bluegrassdistillers.com/wp-content/uploads/2025/11/Mash-Bill-Bottled-in-Bond-Bourbon.webp","u":"https://bluegrassdistillers.com/products/mash-bill-1-bottled-in-bond-bourbon/","pr":"Bluegrass","mk":"b777795d-6400-4663-baf6-1b19a8518b04"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
